final class FxRates implements AutoCloseable {
    private final AtomicReference<Rate> latest = new AtomicReference<>();
    private final Disposable cacheConnection;
    final Flux<Rate> live;

    FxRates(Flux<Rate> feed) {
        // for request handlers: connect now, retry after a second, keep the latest in a field
        this.cacheConnection = feed
            .retryWhen(Retry.fixedDelay(Long.MAX_VALUE, Duration.ofSeconds(1))
                .filter(e -> e instanceof IOException))
            .subscribe(latest::set);
        // for dashboards: connect with the first, disconnect 5 s after the last
        this.live = feed.replay(1).refCount(1, Duration.ofSeconds(5));
    }

    Rate current() { return latest.get(); }

    @Override public void close() { cacheConnection.dispose(); }
}

