class FxRates(feed: Flow<Rate>, scope: CoroutineScope) {
    // for request handlers: .value is not a subscription, so start now
    val cache: StateFlow<Rate?> = feed
        .retry { e -> (e is IOException).also { if (it) delay(1_000) } }
        .stateIn(scope, SharingStarted.Eagerly, null)

    // for dashboards: survive a 5 s reload, then stop and forget the old rate
    val live: StateFlow<Rate?> = feed
        .stateIn(scope, SharingStarted.WhileSubscribed(5_000, replayExpirationMillis = 0), null)

    fun current(): Rate? = cache.value
}
// cancelling `scope` stops both

