class TransitionBus {
    private val bus = MutableSharedFlow<Transition>(extraBufferCapacity = 64)   // SUSPEND, the default
    val events: SharedFlow<Transition> = bus.asSharedFlow()

    // false only when some subscriber already has 64 transitions it hasn't taken;
    // the listener must not acknowledge the record then. With no subscriber it is
    // always true, and the transition goes nowhere.
    fun publish(t: Transition): Boolean = bus.tryEmit(t)
}

// the audit writer takes values off the shared buffer at once, into a channel of its own
suspend fun auditAll(bus: TransitionBus, repo: AuditRepository) =
    bus.events.buffer(1_000).collect { repo.write(it) }

