// Java equivalent: a buffered multicast sink, and a buffer of its own on the audit side
class TransitionBus {
    private final Sinks.Many<Transition> bus = Sinks.many().multicast().onBackpressureBuffer(64, false);

    Flux<Transition> events() { return bus.asFlux(); }

    // false when the buffer is full (FAIL_OVERFLOW); synchronized because a Reactor sink
    // refuses concurrent emits with FAIL_NON_SERIALIZED
    synchronized boolean publish(Transition t) { return bus.tryEmitNext(t).isSuccess(); }
}

Disposable auditAll(TransitionBus bus, AuditRepository repo) {
    return bus.events()
        .onBackpressureBuffer(1_000)
        .publishOn(Schedulers.boundedElastic())
        .subscribe(repo::write);
}
